// Upstream: apis/file_test.go (TestConcurrentThumbsGeneration)
//
// The file API through the compiled executable, on copies of the vendored
// fixture: concurrent thumb requests (one thumb per path, all generated by
// the worker pool inside the executable), the generated thumb's storage
// (thumbs_<name>/<size>_<name> with its .attrs) and its reuse, and the
// fallbacks to the original. test/differential/files/serve.test.ts
// compares the same paths with upstream.

import { afterEach, expect, test } from "bun:test";
import {
  existsSync,
  mkdtempSync,
  openSync,
  readdirSync,
  readFileSync,
  readSync,
  closeSync,
  rmSync,
  statSync,
  writeFileSync,
  writeSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import type { FileField } from "@/fields/file";
import { encodeGif } from "@/files/gif-encode";
import { encodePng } from "@/files/png-raw";

import { writeLargePng, writeNoise } from "@test/differential/files/images";
import { copyDataDir, fixtureDir } from "@test/scenarios/fixture";
import { updateCollection } from "@test/scenarios/prepare";
import { startServer, type RunningServer } from "@test/support/executable";

const roots: string[] = [];
const servers: RunningServer[] = [];

afterEach(async () => {
  for (const server of servers.splice(0)) {
    await server.stop();
  }
  for (const root of roots.splice(0)) {
    rmSync(root, { recursive: true, force: true });
  }
});

function fixtureCopy(): string {
  const root = mkdtempSync(join(tmpdir(), "iglo-base-files-"));
  roots.push(root);
  const dataDir = join(root, "pb_data");
  copyDataDir(fixtureDir, dataDir);
  return dataDir;
}

async function start(dataDir: string, env: Record<string, string> = {}): Promise<string> {
  return (await startProcess(dataDir, env)).url;
}

async function startProcess(
  dataDir: string,
  env: Record<string, string> = {},
): Promise<RunningServer> {
  const server = await startServer([], dataDir, "127.0.0.1", undefined, env);
  servers.push(server);
  return server;
}

// the peak resident memory of a process since the last resetPeak, in bytes
function peakRss(pid: number): number {
  const m = /^VmHWM:\s+(\d+) kB$/m.exec(readFileSync(`/proc/${pid}/status`, "utf8"));
  return Number(m?.[1]) * 1024;
}

function resetPeak(pid: number): void {
  writeFileSync(`/proc/${pid}/clear_refs`, "5");
}

// bytes [start, start + length) of a file
function readRange(path: string, offset: number, length: number): Buffer {
  const fd = openSync(path, "r");
  try {
    const out = Buffer.alloc(length);
    readSync(fd, out, 0, length, offset);
    return out;
  } finally {
    closeSync(fd);
  }
}

const fileKey = "wsmn24bux7wo113/al1h9ijdeojtsjy/300_Jsjq7RdBgA.png";

// demo1's file_one: public, with the three new thumb sizes of the Go test
function prepareDemo1Thumbs(dataDir: string): void {
  updateCollection(dataDir, "demo1", (collection) => {
    const fileField = collection.fields.getByName("file_one") as FileField;
    fileField.protected = false;
    fileField.maxSelect = 1;
    fileField.maxSize = 999999;
    // new thumbs
    fileField.thumbs = ["111x111", "111x222", "111x333"];
  });
}

test("TestConcurrentThumbsGeneration", async () => {
  const dataDir = fixtureCopy();
  prepareDemo1Thumbs(dataDir);
  const url = await start(dataDir);

  const urls = [
    "/api/files/" + fileKey + "?thumb=111x111",
    "/api/files/" + fileKey + "?thumb=111x111", // should still result in single thumb
    "/api/files/" + fileKey + "?thumb=111x222",
    "/api/files/" + fileKey + "?thumb=111x333",
  ];
  const responses = await Promise.all(urls.map((u) => fetch(url + u)));
  for (const res of responses) {
    expect(res.status).toBe(200);
    await res.arrayBuffer();
  }

  // ensure that all new requested thumbs were created
  for (const size of ["111x111", "111x222", "111x333"]) {
    const thumb = join(
      dataDir,
      "storage/wsmn24bux7wo113/al1h9ijdeojtsjy/thumbs_300_Jsjq7RdBgA.png",
      `${size}_300_Jsjq7RdBgA.png`,
    );
    expect(existsSync(thumb)).toBe(true);
    const attrs = JSON.parse(readFileSync(thumb + ".attrs", "utf8")) as Record<string, unknown>;
    expect(attrs["user.content_type"]).toBe("image/png");
    // no metadata: json/v2 writes the nil map as {}
    expect(attrs["user.metadata"]).toEqual({});
  }
});

test("a generated thumb is stored once and then served from storage", async () => {
  const dataDir = fixtureCopy();
  prepareDemo1Thumbs(dataDir);
  const url = await start(dataDir);
  const thumb = join(
    dataDir,
    "storage/wsmn24bux7wo113/al1h9ijdeojtsjy/thumbs_300_Jsjq7RdBgA.png/111x222_300_Jsjq7RdBgA.png",
  );

  const first = await fetch(url + "/api/files/" + fileKey + "?thumb=111x222");
  expect(first.status).toBe(200);
  expect(first.headers.get("content-type")).toBe("image/png");
  expect(first.headers.get("content-disposition")).toBe(
    'inline; filename="111x222_300_Jsjq7RdBgA.png"',
  );
  expect(first.headers.get("x-frame-options")).toBeNull();
  const body = new Uint8Array(await first.arrayBuffer());
  expect(Buffer.from(body).equals(readFileSync(thumb))).toBe(true);
  const stored = statSync(thumb).mtimeMs;

  // a second request reads the stored thumb; a changed stored thumb is
  // served as it is
  writeFileSync(thumb, readFileSync(join(dataDir, "storage", fileKey)));
  const second = await fetch(url + "/api/files/" + fileKey + "?thumb=111x222");
  expect(Buffer.from(await second.arrayBuffer())).toEqual(
    readFileSync(join(dataDir, "storage", fileKey)),
  );
  expect(statSync(thumb).mtimeMs).toBeGreaterThanOrEqual(stored);
});

test("thumbs that cannot be made serve the original", async () => {
  const dataDir = fixtureCopy();
  prepareDemo1Thumbs(dataDir);
  // a corrupt PNG in place of the original (its .attrs still says image/png)
  const original = join(dataDir, "storage", fileKey);
  const bytes = readFileSync(original);
  writeFileSync(original, bytes.subarray(0, 40));
  const url = await start(dataDir, { PB_THUMBS_MAX_SOURCE_PIXELS: "" });

  const res = await fetch(url + "/api/files/" + fileKey + "?thumb=111x111");
  expect(res.status).toBe(200);
  expect(res.headers.get("content-disposition")).toBe('inline; filename="300_Jsjq7RdBgA.png"');
  expect(Buffer.from(await res.arrayBuffer())).toEqual(bytes.subarray(0, 40));
  expect(
    existsSync(
      join(
        dataDir,
        "storage/wsmn24bux7wo113/al1h9ijdeojtsjy/thumbs_300_Jsjq7RdBgA.png/111x111_300_Jsjq7RdBgA.png",
      ),
    ),
  ).toBe(false);
});

test("an original over PB_THUMBS_MAX_SOURCE_PIXELS is served as it is", async () => {
  const dataDir = fixtureCopy();
  prepareDemo1Thumbs(dataDir);
  const url = await start(dataDir, { PB_THUMBS_MAX_SOURCE_PIXELS: "10" });

  const res = await fetch(url + "/api/files/" + fileKey + "?thumb=111x111");
  expect(res.status).toBe(200);
  expect(Buffer.from(await res.arrayBuffer())).toEqual(
    readFileSync(join(dataDir, "storage", fileKey)),
  );
});

// cast.ToInt64 reads Go integer literals with digit separators
for (const limit of ["1_000", "0x_3e8", "0_1750"]) {
  test(`PB_THUMBS_MAX_SOURCE_PIXELS=${limit} (1000) serves the original`, async () => {
    const dataDir = fixtureCopy();
    prepareDemo1Thumbs(dataDir);
    const url = await start(dataDir, { PB_THUMBS_MAX_SOURCE_PIXELS: limit });

    // the 320x201 original is over the limit
    const res = await fetch(url + "/api/files/" + fileKey + "?thumb=111x111");
    expect(res.status).toBe(200);
    expect(res.headers.get("content-disposition")).toBe('inline; filename="300_Jsjq7RdBgA.png"');
    expect(Buffer.from(await res.arrayBuffer())).toEqual(
      readFileSync(join(dataDir, "storage", fileKey)),
    );
  });
}

test("an original over PB_THUMBS_MAX_SOURCE_PIXELS is not read into memory", async () => {
  const dataDir = fixtureCopy();
  prepareDemo1Thumbs(dataDir);
  // a valid 4000x2000 PNG of about 24 MB in place of the original
  const original = join(dataDir, "storage", fileKey);
  writeLargePng(original, 4000, 2000, 1);
  const size = statSync(original).size;
  expect(size).toBeGreaterThan(24_000_000);
  const server = await startProcess(dataDir, { PB_THUMBS_MAX_SOURCE_PIXELS: "1000" });
  const target = server.url + "/api/files/" + fileKey + "?thumb=100x100";

  // a first request warms the server up; the measured one is the same
  // request for another uncached thumb
  const warm = await fetch(target, { headers: { Range: "bytes=0-0" } });
  await warm.arrayBuffer();
  resetPeak(server.pid);
  const before = peakRss(server.pid);
  // the range keeps the served original out of the measurement
  const res = await fetch(target.replace("100x100", "111x111"), {
    headers: { Range: "bytes=0-0" },
  });
  expect(res.status).toBe(206);
  expect(res.headers.get("content-range")).toBe(`bytes 0-0/${size}`);
  expect(new Uint8Array(await res.arrayBuffer())).toEqual(
    new Uint8Array(readRange(original, 0, 1)),
  );
  const growth = peakRss(server.pid) - before;
  // reading the original whole would add at least its size
  expect(growth).toBeLessThan(size / 2);
  expect(
    existsSync(
      join(
        dataDir,
        "storage/wsmn24bux7wo113/al1h9ijdeojtsjy/thumbs_300_Jsjq7RdBgA.png/111x111_300_Jsjq7RdBgA.png",
      ),
    ),
  ).toBe(false);
});

test("a multipart/byteranges body over 16 MiB has its Content-Length", async () => {
  const dataDir = fixtureCopy();
  prepareDemo1Thumbs(dataDir);
  const original = join(dataDir, "storage", fileKey);
  writeNoise(original, 24_000_000, 2);
  const server = await startProcess(dataDir);
  const target = server.url + "/api/files/" + fileKey;
  const headers = { Range: "bytes=0-9437183,10485760-19922943" };

  const head = await fetch(target, { method: "HEAD", headers });
  expect(head.status).toBe(206);
  const length = Number(head.headers.get("content-length"));
  expect(length).toBeGreaterThan(16 << 20);

  resetPeak(server.pid);
  const before = peakRss(server.pid);
  const res = await fetch(target, { headers });
  expect(res.status).toBe(206);
  expect(res.headers.get("content-length")).toBe(String(length));
  expect(res.headers.get("transfer-encoding")).toBeNull();
  const boundary = /^multipart\/byteranges; boundary=([0-9a-f]{60})$/.exec(
    res.headers.get("content-type") ?? "",
  )?.[1];
  expect(boundary).toBeDefined();
  const body = Buffer.from(await res.arrayBuffer());
  expect(peakRss(server.pid) - before).toBeLessThan(16 << 20);
  expect(body.length).toBe(length);
  const part = (i: number, from: number, to: number): Buffer =>
    Buffer.concat([
      Buffer.from(
        `${i === 0 ? "" : "\r\n"}--${boundary}\r\nContent-Range: bytes ${from}-${to}/24000000\r\nContent-Type: image/png\r\n\r\n`,
      ),
      readRange(original, from, to - from + 1),
    ]);
  expect(
    body.equals(
      Buffer.concat([
        part(0, 0, 9437183),
        part(1, 10485760, 19922943),
        Buffer.from(`\r\n--${boundary}--\r\n`),
      ]),
    ),
  ).toBe(true);

  // the spooled body is removed once the response has it
  await Bun.sleep(100);
  const tempDir = join(dataDir, ".pb_temp_to_delete");
  expect(existsSync(tempDir) ? readdirSync(tempDir) : []).toEqual([]);
});

test("Range, conditional requests and download=1", async () => {
  const dataDir = fixtureCopy();
  prepareDemo1Thumbs(dataDir);
  const url = await start(dataDir);
  const full = readFileSync(join(dataDir, "storage", fileKey));
  const target = url + "/api/files/" + fileKey;

  const plain = await fetch(target);
  const lastModified = plain.headers.get("last-modified") as string;
  expect(lastModified).toMatch(/^[A-Z][a-z]{2}, \d{2} [A-Z][a-z]{2} \d{4} \d{2}:\d{2}:\d{2} GMT$/);
  expect(plain.headers.get("accept-ranges")).toBe("bytes");
  await plain.arrayBuffer();

  const range = await fetch(target, { headers: { Range: "bytes=10-19" } });
  expect(range.status).toBe(206);
  expect(range.headers.get("content-range")).toBe(`bytes 10-19/${full.length}`);
  expect(Buffer.from(await range.arrayBuffer())).toEqual(full.subarray(10, 20));

  const notModified = await fetch(target, { headers: { "If-Modified-Since": lastModified } });
  expect(notModified.status).toBe(304);
  expect(notModified.headers.get("content-type")).toBeNull();
  await notModified.arrayBuffer();

  const old = await fetch(target, {
    headers: { "If-Modified-Since": "Mon, 01 Jan 2001 00:00:00 GMT" },
  });
  expect(old.status).toBe(200);
  await old.arrayBuffer();

  const unsatisfiable = await fetch(target, { headers: { Range: `bytes=${full.length}-` } });
  expect(unsatisfiable.status).toBe(416);
  expect(unsatisfiable.headers.get("content-range")).toBe(`bytes */${full.length}`);
  await unsatisfiable.arrayBuffer();

  const download = await fetch(target + "?download=1");
  expect(download.headers.get("content-disposition")).toBe(
    'attachment; filename="300_Jsjq7RdBgA.png"',
  );
  await download.arrayBuffer();
});

// a valid animated GIF: frames of 512x512 noise, all the same frame
function writeAnimatedGif(path: string, frames: number): void {
  const pix = new Uint8Array(512 * 512 * 4);
  let x = 1;
  for (let i = 0; i < pix.length; i++) {
    x = (x * 1103515245 + 12345) >>> 0;
    pix[i] = i % 4 === 3 ? 255 : x >>> 24;
  }
  const one = encodeGif(pix, 512, 512);
  const fields = one[10] as number;
  const framesAt = 13 + (fields & 0x80 ? 3 << (1 + (fields & 7)) : 0);
  const frame = one.subarray(framesAt, one.length - 1);
  const fd = openSync(path, "w");
  try {
    writeSync(fd, one.subarray(0, framesAt));
    for (let i = 0; i < frames; i++) {
      writeSync(fd, frame);
    }
    writeSync(fd, new Uint8Array([0x3b]));
  } finally {
    closeSync(fd);
  }
}

test("only the first frame of an animated GIF original is read", async () => {
  const dataDir = fixtureCopy();
  prepareDemo1Thumbs(dataDir);
  const original = join(dataDir, "storage", fileKey);
  writeAnimatedGif(original, 256);
  const size = statSync(original).size;
  expect(size).toBeGreaterThan(45_000_000);
  const server = await startProcess(dataDir);
  const target = server.url + "/api/files/" + fileKey + "?thumb=100x100";

  // a first thumb warms the worker up; the measured one is another
  // uncached thumb of the same original
  const warm = await fetch(target);
  expect(warm.status).toBe(200);
  await warm.arrayBuffer();
  resetPeak(server.pid);
  const before = peakRss(server.pid);
  const res = await fetch(target.replace("100x100", "111x222"));
  expect(res.status).toBe(200);
  const body = new Uint8Array(await res.arrayBuffer());
  // a thumb, not the original
  expect(body.length).toBeLessThan(size / 10);
  const growth = peakRss(server.pid) - before;
  // a thumb itself costs about 20 MB here (the same for a one-frame
  // original); reading the original whole would add at least its size
  expect(growth).toBeLessThan(size * 0.75);
  expect(
    existsSync(
      join(
        dataDir,
        "storage/wsmn24bux7wo113/al1h9ijdeojtsjy/thumbs_300_Jsjq7RdBgA.png/111x222_300_Jsjq7RdBgA.png",
      ),
    ),
  ).toBe(true);
});

const u24 = (v: number): number[] => [v & 0xff, (v >> 8) & 0xff, (v >> 16) & 0xff];
const u32 = (v: number): number[] => [...u24(v), v >>> 24];

// a RIFF chunk with its padding byte
function riffChunk(id: string, data: Uint8Array): Uint8Array {
  const out = new Uint8Array(8 + data.length + (data.length & 1));
  out.set(new TextEncoder().encode(id));
  out.set(u32(data.length), 4);
  out.set(data, 8);
  return out;
}

// a valid animated WebP: VP8X with the animation flag, ANIM, and frames of
// 512x512 lossless noise in ANMF chunks (no VP8 or VP8L chunk at the top
// level), written frame by frame
async function writeAnimatedWebp(path: string, frames: number): Promise<number> {
  const pix = new Uint8Array(512 * 512 * 4);
  let x = 7;
  for (let i = 0; i < pix.length; i++) {
    x = (x * 1103515245 + 12345) >>> 0;
    pix[i] = i % 4 === 3 ? 255 : x >>> 24;
  }
  const still = await new Bun.Image(encodePng({ pix, width: 512, height: 512 }))
    .webp({ lossless: true })
    .bytes();
  // the VP8L chunk, header included
  const vp8l = still.subarray(12);
  const anmfHead = [...u24(0), ...u24(0), ...u24(511), ...u24(511), ...u24(50), 0];
  const anmfData = new Uint8Array(anmfHead.length + vp8l.length);
  anmfData.set(anmfHead);
  anmfData.set(vp8l, anmfHead.length);
  const anmf = riffChunk("ANMF", anmfData);
  const vp8x = riffChunk("VP8X", new Uint8Array([0x02, 0, 0, 0, ...u24(511), ...u24(511)]));
  const anim = riffChunk("ANIM", new Uint8Array(6));
  const riffLen = 4 + vp8x.length + anim.length + frames * anmf.length;
  const fd = openSync(path, "w");
  try {
    writeSync(fd, new Uint8Array([...new TextEncoder().encode("RIFF"), ...u32(riffLen)]));
    writeSync(fd, new TextEncoder().encode("WEBP"));
    writeSync(fd, vp8x);
    writeSync(fd, anim);
    for (let i = 0; i < frames; i++) {
      writeSync(fd, anmf);
    }
  } finally {
    closeSync(fd);
  }
  return 8 + riffLen;
}

test("an animated WebP original serves the original without being read whole", async () => {
  const dataDir = fixtureCopy();
  prepareDemo1Thumbs(dataDir);
  const original = join(dataDir, "storage", fileKey);
  const size = await writeAnimatedWebp(original, 700);
  expect(statSync(original).size).toBe(size);
  expect(size).toBeGreaterThan(45_000_000);
  const server = await startProcess(dataDir);
  const target = server.url + "/api/files/" + fileKey + "?thumb=100x100";

  // the range keeps the served original out of the measurement
  const warm = await fetch(target, { headers: { Range: "bytes=0-0" } });
  expect(warm.status).toBe(206);
  await warm.arrayBuffer();
  resetPeak(server.pid);
  const before = peakRss(server.pid);
  const res = await fetch(target.replace("100x100", "111x222"), {
    headers: { Range: "bytes=0-0" },
  });
  expect(res.status).toBe(206);
  expect(res.headers.get("content-range")).toBe(`bytes 0-0/${size}`);
  await res.arrayBuffer();
  const growth = peakRss(server.pid) - before;
  // reading the original whole would add at least its size
  expect(growth).toBeLessThan(size / 4);
  expect(
    existsSync(
      join(
        dataDir,
        "storage/wsmn24bux7wo113/al1h9ijdeojtsjy/thumbs_300_Jsjq7RdBgA.png/111x222_300_Jsjq7RdBgA.png",
      ),
    ),
  ).toBe(false);
});
